stone.map=texture(1024,512,(ct,w,h)=>{ct.fillStyle='#747769';ct.fillRect(0,0,w,h);for(let row=0;row<8;row++){let x=row%2?-70:0;while(x<w){const width=55+rnd()*110,yy=row*64;ct.globalAlpha=.9;ct.fillStyle=['#9e9e8d','#b1ae9b','#888d7c','#aaa694'][Math.floor(rnd()*4)];ct.beginPath();ct.roundRect(x+3,yy+4,width-6,55+rnd()*3,8);ct.fill();ct.strokeStyle='#c4bda9';ct.lineWidth=1;ct.stroke();x+=width;}}});stone.map.repeat.set(2,1);
roof.map=texture(1024,1024,(ct,w,h)=>{ct.fillStyle='#6a6c62';ct.fillRect(0,0,w,h);for(let row=0;row<16;row++)for(let col=-1;col<16;col++){const x=col*68+(row%2)*34,y=row*64;const shade=94+Math.floor(rnd()*35);ct.fillStyle=`rgb(${shade+5},${shade+5},${shade})`;ct.fillRect(x,y,65,64);ct.fillStyle='#4b514b';ct.fillRect(x,y+59,65,5);ct.strokeStyle='#a6a18f';ct.globalAlpha=.3;for(let j=0;j<8;j++){ct.beginPath();ct.moveTo(x+5+j*7,y+3);ct.lineTo(x+3+j*7,y+57);ct.stroke();}ct.globalAlpha=1;}});roof.map.repeat.set(1.5,1.5);
cloth.map=texture(256,256,(ct,w,h)=>{ct.fillStyle='#f0e4cb';ct.fillRect(0,0,w,h);ct.fillStyle='#a24e3c';ct.globalAlpha=.45;for(let x=0;x<w;x+=32)ct.fillRect(x,0,12,h);for(let y=0;y<h;y+=32)ct.fillRect(0,y,w,12);ct.globalAlpha=1;});cloth.map.repeat.set(2,2);
