const M={timber,beam,shutter,stone,cream,black,glass,copper,cloth,roof};
function add(g,m,p){const a=new T.Mesh(g,m);a.castShadow=true;a.receiveShadow=true;p.add(a);return a;}
function box(w,h,d,m,x,y,z,p){const a=add(w>6&&d>3?new T.BoxGeometry(w,h,d):softenBox(w,h,d,Math.min(.035,w*.08,h*.08,d*.08)),m,p);a.position.set(x,y,z);return a;}
