function gable(z,p){const shape=new T.Shape();shape.moveTo(-4.25,3.7);shape.lineTo(4.25,3.7);shape.lineTo(0,6.02);shape.closePath();if(z>0)for(const x of[-1.22,1.22]){const hole=new T.Path(),w=1.28*.64,h=1.35*.64;hole.moveTo(x-w/2,4.55-h/2);hole.lineTo(x-w/2,4.55+h/2);hole.lineTo(x+w/2,4.55+h/2);hole.lineTo(x+w/2,4.55-h/2);hole.closePath();shape.holes.push(hole);}const geo=new T.ExtrudeGeometry(shape,{depth:.12,bevelEnabled:false,steps:1,curveSegments:1});geo.translate(0,0,z-.12);const face=add(geo,timber,p);face.userData.kind=z>0?'pierced-front-gable':'rear-gable';}

