for(const x of[-.72,.72])box(.15,2.65,.3,beam,x,1.64,3.2,g);box(1.54,.15,.3,beam,0,2.89,3.2,g);box(1.26,2.42,.1,timber,0,1.57,3.08,g);for(const x of[-.38,0,.38])box(.025,2.25,.02,beam,x,1.57,3.14,g);sphere(.055,copper,.43,1.55,3.2,g);box(2,.12,.85,stone,0,.24,3.62,g);box(2.35,.12,.45,stone,0,.1,4.12,g);
