for(const side of[-1,1]){for(let i=0;i<3;i++){const z=-1.7+i*1.75;const frame=box(.08,1.45,1.25,beam,side*4.31,2.05,z,g),pane=box(.09,1.22,1.03,glass,side*4.36,2.05,z,g);box(.11,.055,1.1,cream,side*4.42,2.05,z,g);box(.11,1.24,.055,cream,side*4.42,2.05,z,g);}}
// The 2D reference's sheltered wood store, amber windows and rounded stone footing.
const shelter=box(1.9,.12,3.1,timber,-5.05,2.1,-.5,g);shelter.rotation.z=.16;for(const z of[-1.8,.85])rod([-5.7,.1,z],[-5.7,1.95,z],.065,beam,g);colliders.push({x:-21.25,z:-8.5,w:1.5,d:2.8});
const masonry=new T.InstancedMesh(new T.IcosahedronGeometry(1,2),stone,22),stonePose=new T.Object3D();for(let i=0;i<22;i++){stonePose.position.set(-4.05+i%11*.81,.15+Math.floor(i/11)*.25,3.42);stonePose.scale.set(.39,.145,.2);stonePose.rotation.set((rnd()-.5)*.14,(rnd()-.5)*.2,(rnd()-.5)*.06);stonePose.updateMatrix();masonry.setMatrixAt(i,stonePose.matrix);}masonry.castShadow=true;masonry.receiveShadow=true;g.add(masonry);masonry.userData.kind='rounded-stone-footing';
